def findN(sum):
    sum = abs(sum)
    i = 0
    num = 0
    while num <= sum:
        num += i
        i += 1
    num -= i - 1
    i -= 2
    if num == sum:
        print(i)
    else:
        m = i + 1
        tri = num + m
        diff = tri - sum
        if diff % 2 == 0:
            print(m)
        else:
            if m % 2 == 0:
                print(m + 1)
            else:
                print(m + 2)


x = int(input())
findN(x)

